local A=ASAdvisor; local count=0; local function check(ok,name) assert(ok,name); count=count+1; end
local originalZone,originalCards,originalClass=AZS_ZONE,AZS_CARDS,UnitClass;
UnitClass=function() return "Hunter","HUNTER"; end; AZS_ZONE={run="tracking-1",hub=0};
AZS_CARDS={kind="spell",bn=3,cards={{key="aimed_shot"},{key="rapid_fire"}}};
A.ObserveBanishCommand("OTHER","banish 1"); check(not A.pendingBanish,"unrelated outgoing traffic is ignored");
A.ObserveBanishCommand("AZSCMD","banish 1"); check(A.pendingBanish and not A.RunBans().spells.aimed_shot,"clicking ban waits for server confirmation");
