AZS_ZONE={run="reload-bootstrap"}; check(not A.RunBans().spells.aimed_shot,"transient zone has its own empty journal");
AZS_ZONE={run="tracking-1",hub=0}; A.pendingBanish=nil;
check(A.RunBans()==record and A.RunBans().spells.aimed_shot,"returning from reload bootstrap restores the original confirmed ban");
AZS_CARDS.bn=2; A.ObserveBanishCommand("AZSCMD","banish 2"); A.pendingBanish=nil;
check(record.pending and not record.spells.rapid_fire,"pending command survives runtime reset without pretending confirmation");
AZS_CARDS.bn=1; A.ConfirmBanish(); check(record.spells.rapid_fire and not record.pending,"late server confirmation after reload commits the pending spell");
-- Preserve the subsequent tracker fixture's one banned spell.
record.spells.rapid_fire=nil;
AZS_ZONE={}; check(A.RunBans()==record,"partial reload snapshot does not erase run bans"); AZS_ZONE={run="tracking-1",hub=0};
local live={inRun=true,spells={aimed_shot={rank=2,cdmax=1},rapid_fire={rank=1,cdmax=10}},gear={},banned=record.spells};
local b={class="HUNTER",spells={{key="aimed_shot",rank=0},{key="rapid_fire",rank=0,banish=true}},items={"south_seas_kelp","enlightenment","jeklik"},itemRules={}};
local spells=A.TrackerEntries(b,live); check(spells[1].banned and spells[1].detail=="" and spells[1].rank==nil,"actual ban entry has neither stat line nor rank"); check(not spells[2].banned,"manual plan checkbox is not a completed ban");
check(A.ScoreSpell(b,{key="aimed_shot",lines="d20"},live,1).score==0,"confirmed banned spell cannot be recommended again");
live.gear={{slot="amulet",name="Choker of Enlightenment",text="Gold 20%"}};
local _,items=A.TrackerEntries(b,live); check(#items==2 and items[1].row.key=="south_seas_kelp" and items[2].row.key=="enlightenment","wearing second amulet hides worse backups while retaining better target");
live.gear={{slot="amulet",name="Pristine Enchanted South Seas Kelp",text="Luck 20%"}}; _,items=A.TrackerEntries(b,live); check(#items==1 and items[1].row.key=="south_seas_kelp","best worn amulet hides all lower backups");
live.gear={}; _,items=A.TrackerEntries(b,live); check(#items==3,"without owned amulet all plan alternatives remain visible");
local ui=ASAdvisorPlanner; if ui:IsShown() then A.ToggleUI(); end;
local active=A.NewBuild("HUNTER"); active.spells=A.Copy(b.spells); active.items={};
AZS_SPELLS={{key="aimed_shot",rank=2,cdmax=1},{key="rapid_fire",rank=1,cdmax=10}}; AZS_GEAR={}; AZS_RUN.ph="playing"; AZSCardsFrame:Hide(); A.offer=false;
ASAdvisorDB.options.trackerMode="detailed"; A.RefreshUI(); local tracker=ASAdvisorTracker;
check(tracker.sectionLabels.banned:IsShown() and tracker.bannedIcons[1]:IsShown(),"detailed tracker renders a separate banned icon strip");
check(tracker.rows[1].row.key=="rapid_fire" and not tracker.rows[2]:IsShown(),"banned spell leaves normal rows without retaining a duplicate");
ASAdvisorDB.options.trackerMode="compact"; A.RefreshUI();
check(tracker.bannedLabel:IsShown() and tracker.icons[1].banned and not tracker.icons[1].rankBadge:IsShown(),"compact tracker separates banned spells and suppresses rank badges");
tracker.icons[1].scripts.OnEnter(tracker.icons[1]); check(A.Plain(tracker.tip.body:GetText())==A.T("Забанены"),"banned icon hover has no spell stats"); tracker.icons[1].scripts.OnLeave(tracker.icons[1]);
AZS_ZONE={run="tracking-2",hub=0}; check(next(A.RunBans().spells)==nil,"new server run clears recorded bans");
AZS_ZONE,AZS_CARDS,UnitClass=originalZone,originalCards,originalClass;
print("Passed "..count.." retired tracker and confirmed ban checks");
